edits.oldText:
fn update_parameter(
    values: RwSignal<BTreeMap<String, f64>>,
    parameter: &Parameter,
    raw: &str,
) -> Option<f64> {
    let value = raw
        .parse::<f64>()
        .ok()?
        .is_finite()
        .then_some(raw.parse::<f64>().ok()?)?;
    let value = value.clamp(parameter.min, parameter.max);

edits.newText:
fn update_parameter(
    values: RwSignal<BTreeMap<String, f64>>,
    parameter: &Parameter,
    raw: &str,
) -> Option<f64> {
    let value = raw.parse::<f64>().ok()?;
    if !value.is_finite() {
        return None;
    }
    let value = value.clamp(parameter.min, parameter.max);

